#include <stdio.h>

/* teste do desafio de MODULO o-estoque-da-loja — counter_protocol (03-tdd 3.9.3).
   Fase VALOR. As duas primeiras funcoes sao conferidas pelo valor devolvido; as
   duas ultimas nao devolvem nada e sao conferidas pelo EFEITO — a lista lida
   posicao a posicao depois da chamada, e as duas casas de saida lidas pelos
   nomes que emprestaram o endereco. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int quantosEmFalta(int estoque[], int n);
int oIndiceDoPrimeiroZero(int estoque[], int n);
void repor(int estoque[], int n, int minimo);
void minimoEMaximo(int estoque[], int n, int *menor, int *maior);

SM_TEST(a_contagem_e_a_busca) {
    /* dois zerados, o primeiro deles na posicao 1 */
    int estoque[6] = {12, 0, 7, 0, 30, 4};
    checa_int("quantos em falta", quantosEmFalta(estoque, 6), 2,
              "o contador sobe uma vez por item zerado, e sao dois");
    checa_int("a posicao do primeiro zerado", oIndiceDoPrimeiroZero(estoque, 6), 1,
              "a busca devolve o INDICE, e o primeiro item e o indice 0");
}

SM_TEST(a_busca_que_nao_acha_e_o_tamanho_que_manda) {
    int cheio[3] = {5, 9, 2};
    checa_int("nenhum zerado", quantosEmFalta(cheio, 3), 0,
              "sem item zerado o contador fica como comecou");
    checa_int("a busca sem achado", oIndiceDoPrimeiroZero(cheio, 3), -1,
              "quando nao ha zerado a funcao devolve -1, nao 0 — 0 seria uma posicao valida");
    int comZero[3] = {5, 9, 0};
    checa_int("o n corta antes do zerado", oIndiceDoPrimeiroZero(comZero, 2), -1,
              "com n igual a 2 o terceiro item nem e olhado: quem manda no percurso e o n");
}

SM_TEST(a_reposicao_muda_a_lista_de_fora) {
    int estoque[5] = {1, 10, 0, 7, 3};
    repor(estoque, 5, 5);
    checa_int("o 1 subiu para o minimo", estoque[0], 5,
              "estava abaixo de 5 e passou a valer exatamente 5");
    checa_int("o 10 ficou como estava", estoque[1], 10,
              "quem ja estava acima do minimo nao e tocado");
    checa_int("o zerado subiu para o minimo", estoque[2], 5,
              "o item em falta tambem e reposto");
    checa_int("o 7 ficou como estava", estoque[3], 7,
              "de novo: acima do minimo, nao mexe");
    checa_int("nao ha mais item em falta", quantosEmFalta(estoque, 5), 0,
              "depois da reposicao nenhum item continua zerado");
}

SM_TEST(o_menor_e_o_maior_pelas_casas_emprestadas) {
    int estoque[6] = {12, 0, 7, 0, 30, 4};
    int menor = 999;
    int maior = 999;
    minimoEMaximo(estoque, 6, &menor, &maior);
    checa_int("o menor escrito na casa", menor, 0,
              "a funcao escreveu na casa de fora pelo endereco que recebeu");
    checa_int("o maior escrito na casa", maior, 30,
              "a mesma chamada respondeu as duas perguntas, uma em cada casa");
    int nenhum[1] = {0};
    int m = 999;
    int M = 999;
    minimoEMaximo(nenhum, 0, &m, &M);
    checa_int("o menor da lista vazia", m, -1,
              "sem item nao ha menor: a guarda escreve -1");
    checa_int("o maior da lista vazia", M, -1,
              "sem item nao ha maior: a guarda escreve -1");
}

