#include <stdio.h>

int quantosEmFalta(int estoque[], int n) {
    int faltam = 0;
    for (int i = 0; i < n; i++) {
        if (estoque[i] == 0) {
            faltam = faltam + 1;
        }
    }
    return faltam;
}

int oIndiceDoPrimeiroZero(int estoque[], int n) {
    for (int i = 0; i < n; i++) {
        if (estoque[i] == 0) {
            return i;
        }
    }
    return -1;
}

void repor(int estoque[], int n, int minimo) {
    for (int i = 0; i < n; i++) {
        if (estoque[i] < minimo) {
            estoque[i] = minimo;
        }
    }
}

void minimoEMaximo(int estoque[], int n, int *menor, int *maior) {
    if (n == 0) {
        *menor = -1;
        *maior = -1;
        return;
    }
    *menor = estoque[0];
    *maior = estoque[0];
    for (int i = 1; i < n; i++) {
        if (estoque[i] < *menor) {
            *menor = estoque[i];
        }
        if (estoque[i] > *maior) {
            *maior = estoque[i];
        }
    }
}
